-- S2-004: tenant-scoped identity and document metadata.
-- UUIDs are generated by the application. Every tenant-owned child keeps tenant_id,
-- and composite foreign keys prevent references across tenants or parent scopes.

CREATE TABLE principals (
    id UUID PRIMARY KEY,
    kind TEXT NOT NULL CHECK (kind IN ('user', 'service')),
    display_name TEXT NOT NULL CHECK (char_length(btrim(display_name)) BETWEEN 1 AND 255),
    state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('pending', 'active', 'suspended', 'deleted')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE identity_links (
    principal_id UUID NOT NULL REFERENCES principals (id) ON DELETE RESTRICT,
    issuer TEXT NOT NULL CHECK (char_length(issuer) BETWEEN 1 AND 2048),
    subject TEXT NOT NULL CHECK (char_length(subject) BETWEEN 1 AND 1024),
    verified_metadata JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(verified_metadata) = 'object'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (issuer, subject)
);
CREATE INDEX identity_links_principal_idx ON identity_links (principal_id);

CREATE TABLE tenants (
    id UUID PRIMARY KEY,
    slug TEXT NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]{0,62}$'),
    name TEXT NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 255),
    state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('pending', 'active', 'suspended', 'archived', 'deleting', 'deleted')),
    plan_id TEXT NOT NULL CHECK (char_length(btrim(plan_id)) BETWEEN 1 AND 128),
    home_region TEXT NOT NULL CHECK (char_length(btrim(home_region)) BETWEEN 1 AND 128),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE tenant_members (
    tenant_id UUID NOT NULL REFERENCES tenants (id) ON DELETE RESTRICT,
    principal_id UUID NOT NULL REFERENCES principals (id) ON DELETE RESTRICT,
    role TEXT NOT NULL CHECK (role IN ('tenant_owner', 'tenant_admin', 'editor', 'commenter', 'viewer')),
    state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('pending', 'active', 'suspended', 'deleted')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, principal_id)
);
CREATE INDEX tenant_members_principal_idx ON tenant_members (principal_id, tenant_id);

CREATE TABLE teams (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants (id) ON DELETE RESTRICT,
    slug TEXT NOT NULL CHECK (slug ~ '^[a-z0-9][a-z0-9-]{0,62}$'),
    name TEXT NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 255),
    state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('pending', 'active', 'suspended', 'archived', 'deleting', 'deleted')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, slug)
);

CREATE TABLE team_members (
    tenant_id UUID NOT NULL,
    team_id UUID NOT NULL,
    principal_id UUID NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('team_manager', 'editor', 'commenter', 'viewer')),
    state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('pending', 'active', 'suspended', 'deleted')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, team_id, principal_id),
    FOREIGN KEY (tenant_id, team_id) REFERENCES teams (tenant_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (tenant_id, principal_id) REFERENCES tenant_members (tenant_id, principal_id) ON DELETE RESTRICT
);
CREATE INDEX team_members_principal_idx ON team_members (tenant_id, principal_id);

CREATE TABLE workspaces (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants (id) ON DELETE RESTRICT,
    owning_team_id UUID,
    name TEXT NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 255),
    state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('pending', 'active', 'suspended', 'archived', 'deleting', 'deleted')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, owning_team_id) REFERENCES teams (tenant_id, id) ON DELETE RESTRICT
);
CREATE INDEX workspaces_tenant_created_idx ON workspaces (tenant_id, created_at DESC, id);

CREATE TABLE workspace_members (
    tenant_id UUID NOT NULL,
    workspace_id UUID NOT NULL,
    principal_id UUID NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('workspace_admin', 'editor', 'commenter', 'viewer')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, workspace_id, principal_id),
    FOREIGN KEY (tenant_id, workspace_id) REFERENCES workspaces (tenant_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (tenant_id, principal_id) REFERENCES tenant_members (tenant_id, principal_id) ON DELETE RESTRICT
);
CREATE INDEX workspace_members_principal_idx ON workspace_members (tenant_id, principal_id);

CREATE TABLE workspace_team_grants (
    tenant_id UUID NOT NULL,
    workspace_id UUID NOT NULL,
    team_id UUID NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('workspace_admin', 'editor', 'commenter', 'viewer')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, workspace_id, team_id),
    FOREIGN KEY (tenant_id, workspace_id) REFERENCES workspaces (tenant_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (tenant_id, team_id) REFERENCES teams (tenant_id, id) ON DELETE RESTRICT
);
CREATE INDEX workspace_team_grants_team_idx ON workspace_team_grants (tenant_id, team_id);

CREATE TABLE projects (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL,
    workspace_id UUID NOT NULL,
    owning_team_id UUID,
    name TEXT NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 255),
    state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('pending', 'active', 'suspended', 'archived', 'deleting', 'deleted')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, workspace_id, id),
    FOREIGN KEY (tenant_id, workspace_id) REFERENCES workspaces (tenant_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (tenant_id, owning_team_id) REFERENCES teams (tenant_id, id) ON DELETE RESTRICT
);
CREATE INDEX projects_workspace_created_idx ON projects (tenant_id, workspace_id, created_at DESC, id);

CREATE TABLE documents (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL,
    workspace_id UUID NOT NULL,
    project_id UUID NOT NULL,
    name TEXT NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 255),
    state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('pending', 'active', 'suspended', 'archived', 'deleting', 'deleted')),
    current_seq BIGINT NOT NULL DEFAULT 0 CHECK (current_seq >= 0),
    fencing_token BIGINT NOT NULL DEFAULT 0 CHECK (fencing_token >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, workspace_id, project_id) REFERENCES projects (tenant_id, workspace_id, id) ON DELETE RESTRICT
);
CREATE INDEX documents_project_created_idx ON documents (tenant_id, project_id, created_at DESC, id);

CREATE TABLE document_members (
    tenant_id UUID NOT NULL,
    document_id UUID NOT NULL,
    principal_id UUID NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('editor', 'commenter', 'viewer')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, document_id, principal_id),
    FOREIGN KEY (tenant_id, document_id) REFERENCES documents (tenant_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (tenant_id, principal_id) REFERENCES tenant_members (tenant_id, principal_id) ON DELETE RESTRICT
);
CREATE INDEX document_members_principal_idx ON document_members (tenant_id, principal_id);

CREATE TABLE document_team_grants (
    tenant_id UUID NOT NULL,
    document_id UUID NOT NULL,
    team_id UUID NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('editor', 'commenter', 'viewer')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, document_id, team_id),
    FOREIGN KEY (tenant_id, document_id) REFERENCES documents (tenant_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (tenant_id, team_id) REFERENCES teams (tenant_id, id) ON DELETE RESTRICT
);
CREATE INDEX document_team_grants_team_idx ON document_team_grants (tenant_id, team_id);
